            [{"index": 0, "value": "alpha"}],
            process_batch([" Alpha "]),
        )

    def test_preserves_result_order(self) -> None:
        self.assertEqual(
            [
                {"index": 0, "value": "second"},
                {"index": 1, "value": "first"},
            ],
            process_batch(["second", "first"]),
        )

