        self.assertEqual(
            [
                {"index": 0, "value": "ok"},
                {"index": 1, "error": "item must be a string"},
                {"index": 2, "value": "still-ok"},
            ],
            process_batch(["ok", 3, "still-ok"]),
        )


if __name__ == "__main__":
    unittest.main()
